transactionScript:
import { By, until } from 'selenium-webdriver';
import { driver, credentials, transaction, test, assert } from 'thousandeyes';

runScript();

async function runScript() {
  const baseUrl = '${DEMO_BASE_URL}';

  // 1. SPA login page.
  await transaction.start('open-spa-login');
  await driver.get(baseUrl + '/login');
  const usernameInput = await driver.wait(until.elementLocated(By.css('input[name=username]')), 15000);
  await transaction.end();

  // 2. Submit credentials.
  await transaction.start('login');
  const passwordInput = await driver.findElement(By.css('input[name=password]'));
  await usernameInput.sendKeys(credentials.get('TE_TX_USERNAME').value);
  await passwordInput.sendKeys(credentials.get('TE_TX_PASSWORD').value);
  await driver.findElement(By.xpath("//button[normalize-space()='Sign in' or normalize-space()='Log in' or @type='submit']")).click();
  // After login the SPA bounces to '/' which renders SendMoney.
  await driver.wait(until.elementLocated(By.css('button.primary[type=submit]')), 15000);
  await transaction.end();

  // 3. Submit a synthetic FPS GBP payment.
  await transaction.start('submit-payment');
  // Force amount to a known value. The 'Amount (minor units)' is the only
  // numeric input on the SendMoney form.
  const amountInput = await driver.findElement(By.css("input[type=number]"));
  await amountInput.clear();
  await amountInput.sendKeys('4200');
  await driver.findElement(By.css('button.primary[type=submit]')).click();
  // Confirmation appears in a div with class 'status-line ok' containing
  // the JSON response (we parse the payment_id out of it).
  const okEl = await driver.wait(until.elementLocated(By.css('.status-line.ok')), 30000);
  const okText = await okEl.getText();
  const idMatch = okText.match(/"payment_id"\s*:\s*"([^"]+)"/);
  assert.ok(idMatch && idMatch[1], 'payment_id missing from /process response');
  const paymentId = idMatch[1];
  test.log('payment_id: ' + paymentId);
  await transaction.end();

  // 4. Recent payments page renders the payment in the gateway list.
  await transaction.start('open-recent-payments');
  await driver.get(baseUrl + '/recent');
  await driver.wait(until.elementLocated(By.css('table')), 15000);
  await transaction.end();

  // 5. Look up the payment_id on the Payment status page.
  await transaction.start('lookup-payment-status');
  await driver.get(baseUrl + '/status');
  // The Payment status page has a single text input + Look up button.
  const lookupInput = await driver.wait(until.elementLocated(By.css('input[type=text]')), 10000);
  await lookupInput.sendKeys(paymentId);
  await driver.findElement(By.xpath("//button[normalize-space()='Look up' or @type='submit']")).click();
  // The /status response is rendered into a <pre>, so wait until it appears
  // with the matching payment_id.
  await driver.wait(async () => {
    const els = await driver.findElements(By.css('pre, .status-line'));
    for (const el of els) {
      const text = await el.getText();
      if (text.indexOf(paymentId) !== -1 && (text.indexOf('"accepted"') !== -1 || text.indexOf('"partial"') !== -1)) {
        return true;
      }
    }
    return false;
  }, 15000, 'never saw accepted/partial status for ' + paymentId);
  await transaction.end();
}
